def fill_column_rule3(col_input, rows=17):
    """
    Transform a single column using the observed pattern:
    1. Get non-zeros and group by value
    2. Sort values by first occurrence (min_row)
    3. Each value v fills from fill_start to fill_end:
       - fill_start = fill_end_of_prev + 1 (or 0 if first)
       - fill_end = min(v.max, first_of_next_larger - 1) if next larger exists
             or first(v) if no next larger exists
    """
    non_zeros = [(r, col_input[r]) for r in range(rows) if col_input[r] != 0]

    if not non_zeros:
        return list(col_input)

    # Find value ranges
    value_min_row = {}
    value_max_row = {}
    for r, v in non_zeros:
        if v not in value_min_row:
            value_min_row[v] = r
            value_max_row[v] = r
        else:
            value_min_row[v] = min(value_min_row[v], r)
            value_max_row[v] = max(value_max_row[v], r)

    # Sort values by min_row
    sorted_vals = sorted(value_min_row.keys(), key=lambda v: value_min_row[v])

    output = [0] * rows
    fill_end = -1

    for v in sorted_vals:
        fill_start = fill_end + 1

        # Find next larger values (by first row order)
        next_larger_first = None
        has_next_larger = False
        for other_v in sorted_vals[sorted_vals.index(v) + 1:]:
            if other_v > v:
                if next_larger_first is None or value_min_row[other_v] < next_larger_first:
                    next_larger_first = value_min_row[other_v]
                has_next_larger = True

        if has_next_larger:
            fill_end = min(value_max_row[v], next_larger_first - 1)
        else:
            fill_end = value_min_row[v]

        # Fill
        if fill_start <= fill_end:
            for r in range(fill_start, fill_end + 1):
                output[r] = v

        fill_end = fill_end  # Update for next

    return output

